import os
import yaml

with open('docker-compose.yml') as f:
    raw = f.read()
data = yaml.safe_load(raw)

services = data.get('services') or {}
assert 'app' in services and 'worker' in services, f"expected 'app' and 'worker' services, got {list(services)}"

REQUIRED = {'DATABASE_URL', 'API_KEY', 'LOG_LEVEL'}

def env_to_dict(env):
    if env is None:
        return {}
    if isinstance(env, dict):
        return {str(k): str(v) for k, v in env.items()}
    out = {}
    for item in env:
        item = str(item)
        if '=' in item:
            k, v = item.split('=', 1)
            out[k] = v
        else:
            out[item] = ''
    return out

app = services['app']
worker = services['worker']
app_env = env_to_dict(app.get('environment'))
worker_env = env_to_dict(worker.get('environment'))

app_env_file = app.get('env_file')
worker_env_file = worker.get('env_file')
uses_env_file = bool(app_env_file) and bool(worker_env_file)
uses_anchor = ('&' in raw) and ('*' in raw)

assert uses_env_file or uses_anchor, (
    'expected the duplicated env vars to be extracted via env_file or a YAML anchor/alias, '
    'but found neither in docker-compose.yml'
)

if uses_env_file:
    def as_list(v):
        return v if isinstance(v, list) else [v]
    ref_files = set(as_list(app_env_file)) | set(as_list(worker_env_file))
    env_file_path = next((rf for rf in ref_files if os.path.exists(rf)), None)
    assert env_file_path, f'env_file referenced ({ref_files}) but file not found on disk'
    env_file_vars = {}
    with open(env_file_path) as ef:
        for line in ef:
            line = line.strip()
            if not line or line.startswith('#') or '=' not in line:
                continue
            k, v = line.split('=', 1)
            env_file_vars[k.strip()] = v.strip()
    missing = REQUIRED - set(env_file_vars)
    assert not missing, f'.env file missing required keys: {missing}'
    still_dup_app = REQUIRED.issubset(set(app_env))
    still_dup_worker = REQUIRED.issubset(set(worker_env))
    assert not (still_dup_app and still_dup_worker), (
        "env vars are still duplicated inline in both services' environment blocks"
    )
else:
    assert REQUIRED.issubset(set(app_env)), f'app missing resolved vars, got {app_env}'
    assert REQUIRED.issubset(set(worker_env)), f'worker missing resolved vars, got {worker_env}'
    for k in REQUIRED:
        assert app_env[k] == worker_env[k], (
            f'{k} differs between app and worker after anchor resolution: '
            f'{app_env[k]!r} vs {worker_env[k]!r}'
        )

print('PASS')
